  "claim": {
    "component_id": "C025.component",
    "value": "An unsuccessful search does not automatically establish that approval never occurred.",
    "scope": "The limit on inferring historical nonoccurrence from search failure.",
    "provenance": {
      "refs": [
        {
          "source_id": "P023",
