        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly states this limit on inference from an unsuccessful search."
    }
  },
  "signal_basis": {
    "component_id": "C025.signal_basis",
    "value": "A search for approval records yields no result, with its search scope and access limitations recorded.",
    "scope": "Approval records within the searched sources and available access.",
    "provenance": {
      "refs": [
        {
          "source_id": "P019",
          "role": "SUPPORT"
        },
        {
          "source_id": "P023",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans identify the unsuccessful approval search and its scope and access qualifications."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C025.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is needed to warrant this bounded limit on inference."
    }
  },
  "rationale": "An unsuccessful search establishes non-discovery within its coverage. Without an additional basis connecting historical approval to discoverable records, it does not establish historical nonoccurrence. The claim correctly limits that inference.",
  "uncertainty": "Whether approval actually occurred remains unresolved; that uncertainty does not undermine the claimed inferential limit.",
